class MainWindow(QMainWindow, Ui_MainWindow):
    def __init__(self, parent=None):
        super(MainWindow, self).__init__(parent)
        self.setupUi(self)

        self.saved_settings = {}  # 用于保存弹窗状态的字典

        self.pushButton_2.clicked.connect(self.start_Camera)
        self.pushButton_6.clicked.connect(self.stop_Camera)
        self.pushButton_9.clicked.connect(self.run_py_file)
        self.camera = None
        # 增加计时器Qtimer
        self.timer = QtCore.QTimer(self)
        self.timer.timeout.connect(self.capture_frame)

        # 你可以在这里创建一个额外的QTimer用于自动关闭QMessageBox
        self.autoCloseTimer = QTimer()

        self.load_models()  # 在init方法中加载模型
        self.segmentation()     # 加载分割模型

