    # 持续显示摄像头捕获的帧
    def display_frame(self, frame):
        self.latest_frame = frame  # 保存最新的帧
        frame_rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
        img = QImage(frame_rgb, frame_rgb.shape[1], frame_rgb.shape[0], QImage.Format_RGB888)
        pixmap = QPixmap.fromImage(img)
        self.label_8.setPixmap(pixmap)
        self.label_8.setScaledContents(True)

    # 截取图片并保存显示
    def capture_frame(self):
        # 假设 'folder_path' 是你想要保存图片的文件夹路径
        folder_path = r'photo/Original'

        # 确保文件夹存在，如果不存在则创建
        if not os.path.exists(folder_path):
            os.makedirs(folder_path)

        if hasattr(self, 'latest_frame'):
            timestamp = time.time()  # 获取当前时间戳
            # 将文件夹路径和时间戳结合，构造完整的文件路径
            filename = os.path.join(folder_path, "plank_{}.jpg".format(timestamp))
            cv2.imwrite(filename, self.latest_frame)  # 保存帧为jpg文件

            # 显示帧在label_12
            frame_rgb = cv2.cvtColor(self.latest_frame, cv2.COLOR_BGR2RGB)
            img = QImage(frame_rgb, frame_rgb.shape[1], frame_rgb.shape[0], QImage.Format_RGB888)
            pixmap = QPixmap.fromImage(img)
            self.label_12.setPixmap(pixmap)
            self.label_12.setScaledContents(True)

            # 运行检测代码
            self.image_detection(filename)
            # 运行计算已检测板材的数量代码
            self.plankNum()

        # 坐标比较，设置阈值，调用进行比较
    def compare_coordinates(self, xmin, ymin, xmax, ymax):
        threshold_box = [(150, 100), (500, 420)]  # 阈值坐标范围
        threshold_x_min, threshold_y_min = threshold_box[0]
        threshold_x_max, threshold_y_max = threshold_box[1]

        # 判断目标框的左上和右下角点坐标是否都在规划的坐标范围内
        if threshold_x_min <= xmin <= threshold_x_max and threshold_y_min <= ymin <= threshold_y_max and threshold_x_min <= xmax <= threshold_x_max and threshold_y_min <= ymax <= threshold_y_max:
            return "中心"
        else:
            return "边缘"

    # 计算缺陷区域的面积大小
    def calculate_defect_area(self, xmin, ymin, xmax, ymax):
        width = xmax - xmin
        height = ymax - ymin
        area = width * height
        return area

    # 实时检测并显示
    def image_detection(self, image_path):
        labels = ['chipping', 'glueOverflow', 'greasyDirt', 'potholes', 'scratches']  # 根据你自己的类别进行定义

        img = Image.open(image_path)
        img_cv = cv2.cvtColor(np.array(img), cv2.COLOR_RGB2BGR)  # 将PIL图像转换为OpenCV图像

        img_center = (img_cv.shape[1] // 2, img_cv.shape[0] // 2)

        # 进行目标检测
        start_time = time.time()
        detections = self.model(img)
        end_time = time.time()

        # 计算检测时间
        detection_time = end_time - start_time

        # 获取标签和对应的置信度
        defect_name = ''
        confidence = 0.0
        if len(detections.xyxy[0]) > 0:
            defect_name = labels[int(detections.xyxy[0][0][5])]
            confidence = float(detections.xyxy[0][0][4])

        image_name = os.path.basename(image_path)  # 获取图片文件名
        # 打印信息
        print('---')
        print('photo_name:{}'.format(image_name))
        print('Defect_name: {}'.format(defect_name))
        print('Defect Count: {}'.format(len(detections.xyxy[0])))
        print('confidence: {}'.format(confidence))
        print('Detection Time: {} seconds'.format(detection_time))
        print('photo_path: {}'.format(image_path))

        defect_count = len(detections.xyxy[0])

        # 找出离中心最远的框
        max_distance = 0
        farthest_box = None

        # 在图像上绘制目标框和类别
        for det in detections.xyxy[0]:
            xmin, ymin, xmax, ymax, _, cls_id = det.tolist()
            # 打印坐标信息
            print('Bounding Box Coordinates: ({}, {}), ({}, {})'.format(int(xmin), int(ymin), int(xmax),
                                                                        int(ymax)))
            cv2.rectangle(img_cv, (int(xmin), int(ymin)), (int(xmax), int(ymax)), (0, 255, 0), 2)
            cv2.putText(img_cv, labels[int(cls_id)], (int(xmin), int(ymin) - 10), cv2.FONT_HERSHEY_SIMPLEX, 0.9,
                        (0, 255, 0), 2)

            box_center = ((xmin + xmax) / 2, (ymin + ymax) / 2)
            distance = ((img_center[0] - box_center[0]) ** 2 + (img_center[1] - box_center[1]) ** 2) ** 0.5
            if distance > max_distance:
                max_distance = distance
                farthest_box = (xmin, ymin, xmax, ymax)

        self.tagged_img = img_cv.copy()  # 在此处保存标记后的图像

        # 将标记后的图像显示在label_13上
        detection_img = QImage(img_cv, img_cv.shape[1], img_cv.shape[0], QImage.Format_RGB888)
        detection_pixmap = QPixmap.fromImage(detection_img)
        self.label_13.setPixmap(detection_pixmap)
        self.label_13.setScaledContents(True)

        # 如果有检测框，对离中心最远的框进行位置比较
        if farthest_box is None:
            print('No defects')
            self.lineEdit_12.setText("No defects")
            self.lineEdit_9.setText("100%")
            self.lineEdit_21.setText("No defects")
            self.lineEdit_27.setText("0")
            self.lineEdit_28.setText("0")
        else:
            xmin, ymin, xmax, ymax = farthest_box

            result = self.compare_coordinates(int(xmin), int(ymin), int(xmax), int(ymax))
            print('Result: {}'.format(result))
            self.lineEdit_21.setText(result)

            defect_area = self.calculate_defect_area(int(xmin), int(ymin), int(xmax), int(ymax))
            one_area = defect_area / 768
            real_area = defect_count * one_area
            # self.lineEdit_32.setText(str(real_area))
            self.lineEdit_27.setText(str(round(real_area * 10, 3)))

            areaRatio = real_area / self.area * 10000
            print("面积占比为：", areaRatio)
            # self.lineEdit_18.setText(str(areaRatio)+"%")
            # print(str(round(areaRatio, 3))+"%")
            self.lineEdit_28.setText(str(round(areaRatio * 10, 2)))

        # 保存标记图像
        self.save_TagImage()

        defect_count = str(round(len(detections.xyxy[0]), 3))

        self.lineEdit_12.setText(defect_name)  # 更新缺陷名称的文本框
        self.lineEdit_20.setText(str(round(len(detections.xyxy[0]), 3)))# 更新缺陷数量的文本框
        # self.lineEdit_9.setText(str(round(confidence, 3)))# 更新置信度的文本框
        self.lineEdit_9.setText("100%")
        self.lineEdit_7.setText(str(round(detection_time, 3)))# 更新检测时间的文本框

        detections_results = []  # 存储检测结果的列表

        result_dict = {
            '图片名称': image_name,
            '病害类别': defect_name,
            '病害数量': defect_count,
            '准确率': round(detection_time, 3),
            '检测耗时（s）': round(detection_time, 2),
            '文件路径': image_path
        }

        detections_results.append(result_dict)

        # 保存检测结果到表格
        if os.path.exists("实时检测结果.xlsx"):
            workbook = op.load_workbook("实时检测结果.xlsx")
            worksheet = workbook.active
        else:
            workbook = op.Workbook()
            worksheet = workbook.create_sheet(index=0)

            header = ['图片名称', '病害类别', '病害数量(个)', '准确率(%)', '检测耗时（s）', '文件路径']
            worksheet.append(header)

        for result_dict in detections_results:
            row_data = [
                result_dict['图片名称'],
                result_dict['病害类别'],
                result_dict['病害数量'],
                result_dict['准确率'],
                result_dict['检测耗时（s）'],
                result_dict['文件路径']
            ]
            worksheet.append(row_data)

        workbook.save('实时检测结果.xlsx')
        print('检测完成，创建表格写入信息成功！')

        # 调用计算判定ABC级代码
        self.judgment(defect_count)
        # 调用损伤程度判定代码
        self.damageJudgment(defect_count)
        # 写入数据库
        self.write_mysql()
        # 调用语音播报
        speak.voice_report(self)
        # 调用imcomingpdf函数,将所有信息传入pdf.py中
        self.run_realtime_report_thread()

    # 保存标记图像
