    # A,B,C级板材判定，并显示在界面上
    def judgment(self, defect_count):
        if int(defect_count) == 0:
            self.numA += 1
            print("numA的值为：", self.numA)
            self.lineEdit_22.setText("A级板材")
            print("此板材为A级板材")
        elif int(defect_count) < 5:
            self.numB += 1
            print("numB的值为：", self.numB)
            self.lineEdit_22.setText("B级板材")
        elif int(defect_count) >= 5:
            self.numC += 1
            print("numC的值为：", self.numC)
            self.lineEdit_22.setText("C级板材")

        # A级数量显示
        self.lineEdit_24.setText(str(self.numA))
        # B级数量显示
        self.lineEdit_25.setText(str(self.numB))
        # C级数量显示
        self.lineEdit_26.setText(str(self.numC))

    # 损伤程度判定
    def damageJudgment(self, defect_count):
        if int(defect_count) == 0:
            self.lineEdit_10.setText("完好")
        elif int(defect_count) <= 3:
            self.lineEdit_10.setText("轻微")
        elif int(defect_count) <= 5:
            self.lineEdit_10.setText("中等")
        elif int(defect_count) >= 6:
            self.lineEdit_10.setText("严重")

    # 板坯数量，A级板占比
    def plankNum(self):
        path = r"photo/Original"  # 文件夹路径
        plankNums = 0
        for file in os.listdir(path):  # file 表示的是文件名
            plankNums = plankNums + 1
        print(plankNums)

        # 板坯数量显示
        self.lineEdit_23.setText(str(plankNums))
        # A级板占比显示
        self.lineEdit_29.setText(str(round(self.numA / plankNums * 100, 2)))

        # 在进行完一次检测后，将数据传入pdf.py中
        # 将所有的信息保存在一个列表中，并转入pdf.py中
        #获取Setting的detectBatch,boardSpec,boardModel,detectNum,transferRate数据
    def imcomingpdf(self):
        # 从全局存储中获取数据
        detectBatch = shared_data.get('detectBatch', '1')
        boardSpec = shared_data.get('boardSpec', '')
        boardModel = shared_data.get('boardModel', '')
        detectNum = shared_data.get('detectNum', '')
        transferRate = shared_data.get('transferRate', '')
        detectType = shared_data.get('detectType', '')
        sampleName = shared_data.get('sampleName', '')

        additional_data = [self.lineEdit_12.text(), self.lineEdit_20.text(), self.lineEdit_9.text(), self.lineEdit_7.text(),
                self.lineEdit_29.text(), self.lineEdit_26.text(), self.lineEdit_25.text(), self.lineEdit_24.text(),
                self.lineEdit_23.text(), self.lineEdit_22.text(), self.lineEdit_10.text(),
                self.lineEdit_21.text(), self.lineEdit_28.text(), self.lineEdit_27.text(),
                self.dateTimeEdit.text()]
        # 添加从 on_save 函数中传递过来的数据
        incoming_data = [
            detectBatch, boardSpec, boardModel, detectNum, transferRate,detectType, sampleName
        ]

        # 将两个数据集合合并
        data = additional_data + incoming_data
        # 打印出自动获取的数据
        print('这是自动获取的数据',detectBatch, boardSpec, boardModel, detectNum, transferRate)

        pdf.pdf_report(data)
        # 打印出所有信息
        # print('这是data传入pdf的数据',data)
